Here is a correct token-bucket implementation with per-key limiting and no exceptions:

```python
import time
from typing import Any

class RateLimiter:
    def __init__(self, max_tokens: int = 10, refill_rate: float = 1.0):
        self.max_tokens = max_tokens
        self.refill_rate = refill_rate
        self._buckets: dict[str, dict[str, Any]] = {}

    def _refill(self, key: str, now: float) -> dict[str, Any]:
        bucket = self._buckets.get(key)
        if bucket is None:
            bucket = {"tokens": float(self.max_tokens), "last": now}
            self._buckets[key] = bucket
            return bucket
        elapsed = now - bucket["last"]
        if elapsed > 0:
            bucket["tokens"] = min(
                float(self.max_tokens),
                bucket["tokens"] + elapsed * self.refill_rate
            )
            bucket["last"] = now
        return bucket

    def allow(self, key: str = 'default') -> bool:
        """Check if a request for the given key is allowed."""
        now = time.time()
        bucket = self._refill(key, now)
        if bucket["tokens"] >= 1.0:
            bucket["tokens"] -= 1.0
            return True
        return False

    def get_tokens(self, key: str = 'default') -> float:
        """Get current token count for a key."""
        now = time.time()
        bucket = self._refill(key, now)
        return float(bucket["tokens"])
